-- DB-2 (lead contract ruling): an image can show one option value (e.g. a colour) instead of a
-- variant. Generated by drizzle-kit; ON DELETE SET NULL added by hand (drizzle-kit 0.31 drops the
-- action on ADD COLUMN). SQLite cannot add a table CHECK without a rebuild, so "not both
-- variant_id and option_value_id" is enforced by triggers.
ALTER TABLE `images` ADD `option_value_id` integer REFERENCES option_values(id) ON DELETE SET NULL;--> statement-breakpoint
CREATE INDEX `images_option_value_idx` ON `images` (`option_value_id`);--> statement-breakpoint
CREATE TRIGGER `images_variant_or_option_value_ins` BEFORE INSERT ON `images`
WHEN NEW.`variant_id` IS NOT NULL AND NEW.`option_value_id` IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'images: variant_id and option_value_id are exclusive');
END;
--> statement-breakpoint
CREATE TRIGGER `images_variant_or_option_value_upd` BEFORE UPDATE OF `variant_id`, `option_value_id` ON `images`
WHEN NEW.`variant_id` IS NOT NULL AND NEW.`option_value_id` IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'images: variant_id and option_value_id are exclusive');
END;
